// apply: configure and return the same object
val user = User().apply { name = "Alice"; age = 30 }

// also: side effect, return same object, `it` for clarity
val validUser = user.also { Log.d("App", "Created user: ${it.name}") }

// let: null-safe transform, returns lambda result
val length: Int? = nullableName?.let { it.trim().length }

// run: this-reference AND different return value
val isValid = user.run { name.isNotBlank() && age >= 18 }

// Avoid: unclear, hard to debug, nested `it`
response.body?.let { body -> body.data?.also { it.forEach { item -> process(item) } } }

// Prefer: explicit, debuggable, self-documenting
val body = response.body ?: return
val items = body.data ?: return
items.forEach { item -> process(item) }
